      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: 95000, gold tier 5% discount = 4750, discounted = 90250, VAT 21% = 18953
  // LOGO-PACK: 120000, explicit 15% discount = 18000, discounted = 102000, VAT 21% = 21420
  // WORKSHOP-DAY: 50000, gold tier 5% discount = 2500, discounted = 47500, VAT 0% = 0
  // subtotal = 265000, discount = 25250, vat = 40373, total = 280123
  assert.equal(totals.subtotal, 265000);
  assert.equal(totals.discount, 25250);
  assert.equal(totals.vat, 40373);
  assert.equal(totals.total, 280123);
});

test('invoiceTotals clamps total to zero with extreme discount and low VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'WORKSHOP-DAY',
        name: 'Workshop (day)',
        qty: 1,
        unitPrice: 100,
        vatRate: 0,
        discountPercent: 100,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 100, discount = 100, vat = 0
  // total should be clamped to 0, not -0
  assert.equal(totals.subtotal, 100);
  assert.equal(totals.discount, 100);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

