import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('renderInvoiceText shows DRAFT for draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.ok(text.startsWith('DRAFT'));
});

test('renderInvoiceText shows invoice number for issued invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const r2 = issueInvoice(r1.value, []);
  const text = renderInvoiceText(r2.value);
  assert.ok(text.startsWith('INV-2025-0001'));
});

test('renderInvoiceText includes customer name', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  assert.equal(lines[1], 'Northwind Studio');
});

test('renderInvoiceText formats single line correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // Line format: qty x name @ unitPrice = lineTotal
  // 10 x Development (hour) @ €95.00 = €950.00
  assert.equal(lines[2], '10 x Development (hour) @ €95.00 = €950.00');
});

test('renderInvoiceText handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  assert.equal(lines.length, 6); // DRAFT, customer, 2 product lines, VAT, total
  assert.equal(lines[2], '10 x Development (hour) @ €95.00 = €950.00');
  assert.equal(lines[3], '1 x Logo package @ €1,200.00 = €1,200.00');
});

test('renderInvoiceText calculates and shows correct total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // 10 * 9500 + 1 * 120000 = 215000, C-001 is gold tier (5% discount = 10750)
  // Discounted = 204250
  // VAT: DEV-HOUR 90250 * 21% = 18953, LOGO-PACK 102000 * 21% = 21420, total VAT = 40373
  // Total = 204250 + 40373 = 244623 cents = €2,446.23
  assert.equal(lines[4], 'VAT: €403.73');
  assert.equal(lines[5], 'Total: €2,446.23');
});

test('renderInvoiceText formats prices with formatEuros', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'STICKER', qty: 100 },
    ],
  });
  const text = renderInvoiceText(r.value);
  // STICKER: unitPrice = 50 cents = €0.50
  // 100 * 50 = 5000, C-001 is gold tier (5% discount = 250), discounted = 4750
  // VAT = 4750 * 21% = 998, Total = 5748 cents = €57.48
  assert.ok(text.includes('€0.50'));
  assert.ok(text.includes('€57.48'));
});

test('renderInvoiceText includes all product details', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'ICON-SET', qty: 5 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // Customer name should be Kite & Co
  assert.equal(lines[1], 'Kite & Co');
  // Line should show: 5 x Icon set (24 icons) @ €9.80 = €49.00
  assert.equal(lines[2], '5 x Icon set (24 icons) @ €9.80 = €49.00');
});

test('renderInvoiceText output is multiline text', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.ok(typeof text === 'string');
  assert.ok(text.includes('\n'));
  const lines = text.split('\n');
  assert.ok(lines.length >= 4); // at least: number, customer, line, total
});

test('renderInvoiceText with issued invoice and multiple lines', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'PRINT-A3', qty: 50 },
    ],
  });
  const r2 = issueInvoice(r1.value, ['INV-2025-0001']);
  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');
  assert.equal(lines[0], 'INV-2025-0002');
  assert.equal(lines[1], 'Blue Fern Bakery');
  // 100 * 37 = 3700 cents = €37.00
  assert.equal(lines[2], '100 x Printed flyer A4 (each) @ €0.37 = €37.00');
  // 50 * 249 = 12450 cents = €124.50
  assert.equal(lines[3], '50 x Printed poster A3 (each) @ €2.49 = €124.50');
  // VAT: 3700 * 9% = 333, 12450 * 9% = 1121 (rounded), total = 1454
  assert.equal(lines[4], 'VAT: €14.54');
  // Total: 16150 + 1454 = 17604 cents = €176.04
  assert.equal(lines[5], 'Total: €176.04');
});

test('renderInvoiceText shows VAT line', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // Should have: number, customer, product line, VAT line, total line
  assert.equal(lines.length, 5);
  assert.ok(lines[3].startsWith('VAT: '));
  assert.ok(lines[4].startsWith('Total: '));
});

test('renderInvoiceText with 0% VAT does not show charge', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // WORKSHOP-DAY has 0% VAT
  assert.equal(lines[3], 'VAT: €0.00');
  // Total should equal subtotal (60000 cents = €600.00)
  assert.equal(lines[4], 'Total: €600.00');
});

test('renderInvoiceText with mixed VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'PRINT-A4', qty: 50 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // DEV-HOUR: 5 * 9500 = 47500, 21% VAT = 9975
  // PRINT-A4: 50 * 37 = 1850, 9% VAT = 167 (rounded)
  // Total VAT = 10142
  // Subtotal = 49350, Total = 59492
  // Format: number, customer, line 1, line 2, VAT, Total
  assert.equal(lines.length, 6);
  assert.ok(lines[4].startsWith('VAT: '));
  assert.ok(lines[5].startsWith('Total: '));
});

