      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: lineTotal = 95000, discount = 9500
  // LOGO-PACK: lineTotal = 120000, discount = 24000
  // subtotal = 215000, total discount = 33500, total = 181500
