test('invoiceTotals with mix of discounted and non-discounted lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: lineTotal = 95000, explicit discount 10% = 9500
  // LOGO-PACK: lineTotal = 120000, gets gold tier discount 5% = 6000
  // subtotal = 215000, total discount = 15500, total = 199500
  assert.equal(totals.subtotal, 215000);
  assert.equal(totals.discount, 15500);
  assert.equal(totals.total, 199500);
});

test('invoiceTotals clamps total to zero when discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 100,
        vatRate: 21,
        discountPercent: 100,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 100, discount = 100, total should be 0, not -0
  assert.equal(totals.subtotal, 100);
  assert.equal(totals.discount, 100);
  assert.equal(totals.total, 0);
});

