      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: 95000, gold tier 5% discount = 4750, discounted = 90250, VAT 21% = 18953
  // LOGO-PACK: 120000, explicit 15% discount = 18000, discounted = 102000, VAT 21% = 21420
