  // subtotal = 275000, discount = 25750, vat = 40373, total = 289623
  assert.equal(totals.subtotal, 275000);
  assert.equal(totals.discount, 25750);
  assert.equal(totals.vat, 40373);
  assert.equal(totals.total, 289623);
});

test('invoiceTotals clamps total to zero with extreme discount and low VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
